/* Skin "mocha-mousse" (Mocha Mousse): the tweakcn preset "mocha-mousse" (Apache-2.0, see NOTICE.md), written by packages/skins/tools/tweakcn-skins.ts.
   On when data-skin="mocha-mousse" is on <html> (the page) or on any element (a tile of /skins/). Values as tweakcn exports them;
   the spacing scale stays the kit's 0.25rem. Fonts: DM Sans (Google Fonts, loaded when the skin is on). */
[data-skin="mocha-mousse"] {
  --background: hsl(55 30% 92%);
  --foreground: hsl(16 15% 29%);
  --card: hsl(55 30% 92%);
  --card-foreground: hsl(16 15% 29%);
  --popover: hsl(0 0% 100%);
  --popover-foreground: hsl(16 15% 29%);
  --primary: hsl(17.7 25.5% 46.9%);
  --primary-foreground: hsl(0 0% 100%);
  --secondary: hsl(37.3 16.7% 43.3%);
  --secondary-foreground: hsl(0 0% 100%);
  --muted: hsl(20 45% 81%);
  --muted-foreground: hsl(13.3 25.1% 35.1%);
  --accent: hsl(20 45% 81%);
  --accent-foreground: hsl(16 15% 29%);
  --destructive: hsl(22.5 14.8% 10.6%);
  --destructive-foreground: hsl(0 0% 100%);
  --border: hsl(37 22% 65%);
  --input: hsl(37 22% 65%);
  --ring: hsl(18 26% 52%);
  --chart-1: hsl(18 26% 52%);
  --chart-2: hsl(14 21% 45%);
  --chart-3: hsl(22 33% 65%);
  --chart-4: hsl(37 22% 65%);
  --chart-5: hsl(22 19% 55%);
  --sidebar: hsl(21 44% 86%);
  --sidebar-foreground: hsl(16 15% 29%);
  --sidebar-primary: hsl(18 26% 52%);
  --sidebar-primary-foreground: hsl(0 0% 100%);
  --sidebar-accent: hsl(22 33% 65%);
  --sidebar-accent-foreground: hsl(0 0% 100%);
  --sidebar-border: hsl(22 19% 55%);
  --sidebar-ring: hsl(18 26% 52%);
  --font-sans: DM Sans, sans-serif;
  --font-serif: Georgia, serif;
  --font-mono: Menlo, monospace;
  --radius: 0.5rem;
  --shadow-2xs: 2px 2px 0px 0px hsl(20 18% 51% / 0.06);
  --shadow-xs: 2px 2px 0px 0px hsl(20 18% 51% / 0.06);
  --shadow-sm: 2px 2px 0px 0px hsl(20 18% 51% / 0.11), 2px 1px 2px -1px hsl(20 18% 51% / 0.11);
  --shadow: 2px 2px 0px 0px hsl(20 18% 51% / 0.11), 2px 1px 2px -1px hsl(20 18% 51% / 0.11);
  --shadow-md: 2px 2px 0px 0px hsl(20 18% 51% / 0.11), 2px 2px 4px -1px hsl(20 18% 51% / 0.11);
  --shadow-lg: 2px 2px 0px 0px hsl(20 18% 51% / 0.11), 2px 4px 6px -1px hsl(20 18% 51% / 0.11);
  --shadow-xl: 2px 2px 0px 0px hsl(20 18% 51% / 0.11), 2px 8px 10px -1px hsl(20 18% 51% / 0.11);
  --shadow-2xl: 2px 2px 0px 0px hsl(20 18% 51% / 0.28);
  --destructive-hover: hsl(22.5 14.8% 4.6%);
}

:is(.dark, [data-theme="dark"]) [data-skin="mocha-mousse"],
[data-skin="mocha-mousse"]:is(.dark, [data-theme="dark"]) {
  --background: hsl(20 15% 15%);
  --foreground: hsl(55 30% 92%);
  --card: hsl(21 13% 21%);
  --card-foreground: hsl(55 30% 92%);
  --popover: hsl(21 13% 21%);
  --popover-foreground: hsl(55 30% 92%);
  --primary: hsl(22 33% 65%);
  --primary-foreground: hsl(20 15% 15%);
  --secondary: hsl(13.8 21.4% 43.9%);
  --secondary-foreground: hsl(55 30% 92%);
  --muted: hsl(16 15% 29%);
  --muted-foreground: hsl(21 31% 73%);
  --accent: hsl(37 22% 65%);
  --accent-foreground: hsl(20 15% 15%);
  --destructive: hsl(0 68.7% 67.5%);
  --destructive-foreground: hsl(20 15% 15%);
  --border: hsl(16 15% 29%);
  --input: hsl(16 15% 29%);
  --ring: hsl(22 33% 65%);
  --chart-1: hsl(22 33% 65%);
  --chart-2: hsl(37 22% 65%);
  --chart-3: hsl(18 26% 52%);
  --chart-4: hsl(14 21% 45%);
  --chart-5: hsl(22 19% 55%);
  --sidebar: hsl(22.5 14.8% 10.6%);
  --sidebar-foreground: hsl(55 30% 92%);
  --sidebar-primary: hsl(22 33% 65%);
  --sidebar-primary-foreground: hsl(22.5 14.8% 10.6%);
  --sidebar-accent: hsl(37 22% 65%);
  --sidebar-accent-foreground: hsl(22.5 14.8% 10.6%);
  --sidebar-border: hsl(16 15% 29%);
  --sidebar-ring: hsl(22 33% 65%);
  --shadow-2xs: 2px 2px 0px 0px hsl(20 18% 30% / 0.06);
  --shadow-xs: 2px 2px 0px 0px hsl(20 18% 30% / 0.06);
  --shadow-sm: 2px 2px 0px 0px hsl(20 18% 30% / 0.11), 2px 1px 2px -1px hsl(20 18% 30% / 0.11);
  --shadow: 2px 2px 0px 0px hsl(20 18% 30% / 0.11), 2px 1px 2px -1px hsl(20 18% 30% / 0.11);
  --shadow-md: 2px 2px 0px 0px hsl(20 18% 30% / 0.11), 2px 2px 4px -1px hsl(20 18% 30% / 0.11);
  --shadow-lg: 2px 2px 0px 0px hsl(20 18% 30% / 0.11), 2px 4px 6px -1px hsl(20 18% 30% / 0.11);
  --shadow-xl: 2px 2px 0px 0px hsl(20 18% 30% / 0.11), 2px 8px 10px -1px hsl(20 18% 30% / 0.11);
  --shadow-2xl: 2px 2px 0px 0px hsl(20 18% 30% / 0.28);
  --destructive-hover: hsl(0 68.7% 73.5%);
}

[data-skin="mocha-mousse"] .shadow-xs { --tw-shadow: var(--shadow-xs); }
[data-skin="mocha-mousse"] .shadow-sm { --tw-shadow: var(--shadow-sm); }
[data-skin="mocha-mousse"] .shadow { --tw-shadow: var(--shadow); }
[data-skin="mocha-mousse"] .shadow-md { --tw-shadow: var(--shadow-md); }
[data-skin="mocha-mousse"] .shadow-lg { --tw-shadow: var(--shadow-lg); }
[data-skin="mocha-mousse"] .shadow-xl { --tw-shadow: var(--shadow-xl); }
